"""Decode protobuf wire format without a schema.

parse(data) returns a flat list of (field_number, wire_type, value) triples:

    wire type 0 -> varint            (value: int)
    wire type 1 -> 64-bit / fixed64  (value: 8 raw bytes)
    wire type 2 -> length-delimited  (value: raw bytes)
    wire type 5 -> 32-bit / fixed32  (value: 4 raw bytes)

Wire types 3 and 4 (groups) and the reserved 6 and 7 are rejected, as are
truncated buffers and varints longer than 10 bytes. Every failure raises
WireError carrying the byte offset where the problem was detected.
"""

from __future__ import annotations

import struct

__all__ = ["WireError", "parse", "try_message", "encode"]

VARINT = 0
FIXED64 = 1
LEN = 2
START_GROUP = 3
END_GROUP = 4
FIXED32 = 5

MAX_VARINT_BYTES = 10


class WireError(ValueError):
    """Raised on malformed protobuf wire data."""

    def __init__(self, message: str, offset: int):
        super().__init__(f"{message} at byte offset {offset}")
        self.offset = offset


def _read_varint(data: bytes, pos: int) -> tuple[int, int]:
    """Decode a base-128 varint starting at *pos*.

    Returns (value, new_pos). Raises WireError on truncation or if the
    varint exceeds MAX_VARINT_BYTES bytes.
    """
    start = pos
    result = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise WireError("truncated varint", start)
        if pos - start >= MAX_VARINT_BYTES:
            raise WireError("varint exceeds 10 bytes", start)
        byte = data[pos]
        result |= (byte & 0x7F) << shift
        pos += 1
        if not (byte & 0x80):
            return result, pos
        shift += 7


def parse(data: bytes) -> list[tuple[int, int, object]]:
    """Parse a complete protobuf message buffer into (field, wire_type, value)."""
    fields: list[tuple[int, int, object]] = []
    pos = 0
    n = len(data)
    while pos < n:
        tag_start = pos
        key, pos = _read_varint(data, pos)
        field_number = key >> 3
        wire_type = key & 0x07

        if wire_type == VARINT:
            value, pos = _read_varint(data, pos)
        elif wire_type == FIXED64:
            if pos + 8 > n:
                raise WireError(
                    f"truncated 64-bit field ({n - pos} of 8 bytes present)", pos
                )
            value = bytes(data[pos : pos + 8])
            pos += 8
        elif wire_type == LEN:
            if pos >= n:
                raise WireError("truncated length prefix", pos)
            length, pos = _read_varint(data, pos)
            if pos + length > n:
                raise WireError(
                    f"length-delimited field overruns buffer "
                    f"(need {length}, {n - pos} available)",
                    pos,
                )
            value = bytes(data[pos : pos + length])
            pos += length
        elif wire_type == FIXED32:
            if pos + 4 > n:
                raise WireError(
                    f"truncated 32-bit field ({n - pos} of 4 bytes present)", pos
                )
            value = bytes(data[pos : pos + 4])
            pos += 4
        elif wire_type in (START_GROUP, END_GROUP):
            kind = "start-group" if wire_type == START_GROUP else "end-group"
            raise WireError(f"unsupported wire type 3/4 ({kind})", tag_start)
        else:  # 6 or 7
            raise WireError(f"reserved wire type {wire_type}", tag_start)

        fields.append((field_number, wire_type, value))
    return fields


def try_message(data: bytes) -> list[tuple[int, int, object]] | None:
    """Heuristic nesting check: return the parsed fields iff *data* parses
    cleanly as a whole message, otherwise None."""
    try:
        return parse(data)
    except WireError:
        return None


def _encode_varint(value: int) -> bytes:
    out = bytearray()
    while True:
        byte = value & 0x7F
        value >>= 7
        if value:
            out.append(byte | 0x80)
        else:
            out.append(byte)
            return bytes(out)


def encode(fields: list[tuple[int, int, object]]) -> bytes:
    """Encode (field_number, wire_type, value) triples back to wire format."""
    out = bytearray()
    for field_number, wire_type, value in fields:
        if field_number < 0:
            raise ValueError(f"invalid field number {field_number}")
        if wire_type not in (VARINT, FIXED64, LEN, FIXED32):
            raise ValueError(f"unsupported wire type {wire_type}")
        key = (field_number << 3) | wire_type
        out += _encode_varint(key)
        if wire_type == VARINT:
            if value < 0:
                # Negative ints encode as two's-complement 64-bit varints.
                value &= (1 << 64) - 1
            out += _encode_varint(value)
        elif wire_type == FIXED64:
            out += struct.pack("<Q", int.from_bytes(value, "little"))
        elif wire_type == LEN:
            out += _encode_varint(len(value)) + bytes(value)
        elif wire_type == FIXED32:
            out += struct.pack("<I", int.from_bytes(value, "little"))
    return bytes(out)

